    branches: [main]

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Set up Node.js 22
        uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: pnpm

      - name: Install pnpm 9
        uses: pnpm/action-setup@v2
        with:
          version: 9

      - name: Install dependencies (include devDependencies of root)
        run: pnpm install --include-workspace-root

      - name: Install yaml for lockfile manipulation
        run: pnpm add -D yaml

      - name: Trim devDependencies from pnpm-lock.yaml except root
        run: |
          node - <<'NODE'
          const fs = require('fs');
          const yaml = require('yaml');
          const lockPath = 'pnpm-lock.yaml';
          const lock = yaml.parse(fs.readFileSync(lockPath, 'utf8'));
          const packages = lock.packages;
          const rootPath = '.';
          for (const pkgPath in packages) {
            const pkg = packages[pkgPath];
            if (pkg.dev && pkgPath !== rootPath) {
              delete packages[pkgPath];
            }
          }
          lock.packages = packages;
          fs.writeFileSync(lockPath, yaml.stringify(lock));
          console.log('Trimmed devDependencies from lockfile except root.');
          NODE

      - name: Reinstall using trimmed lockfile
        run: pnpm install --frozen-lockfile

      - name: Run tests
        run: pnpm test
